(function(){
  function safeUrl(url){try{const parsed=new URL(url);return['http:','https:'].includes(parsed.protocol)?parsed.href:'#'}catch{return'#'}}
  function isolatedAdUrl(code,center=true){const alignment=center?'justify-content:center;':'';const html=`<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="referrer" content="strict-origin-when-cross-origin"><base target="_blank"><style>html,body{margin:0;min-height:100%;background:transparent;display:flex;align-items:flex-start;${alignment}overflow:hidden}img,iframe{max-width:100%}</style></head><body>${code}</body></html>`;return`data:text/html;charset=utf-8,${encodeURIComponent(html)}`}
  function dimensions(size='300x250'){const[w,h]=size.split('x').map(Number);return{w:w||300,h:h||250}}
  function renderPageAd(host,data){if(!host||!data?.active){if(host)host.hidden=true;return}host.hidden=false;host.innerHTML='';const size=data.size||'728x90',dim=dimensions(size);host.dataset.size=size;host.style.setProperty('--ad-w',`${dim.w}px`);host.style.setProperty('--ad-h',`${dim.h}px`);const label=document.createElement('span');label.textContent=data.label||'IKLAN';host.append(label);if(data.mode==='code'&&data.code){const frame=document.createElement('iframe');frame.title=data.label||'Iklan';frame.referrerPolicy='strict-origin-when-cross-origin';frame.src=isolatedAdUrl(data.code);host.append(frame);return}const link=document.createElement('a');link.href=safeUrl(data.url);link.target='_blank';link.rel='noopener noreferrer sponsored';if(data.image){const img=document.createElement('img');img.src=data.image;img.alt=data.label||'Iklan';link.append(img)}else{link.className='page-ad-placeholder';link.innerHTML='<b>Ruang iklan</b><small>Atur dari halaman admin</small>'}host.append(link)}
  function rail(side,data){if(!data?.active)return;const size=data.size==='160x600'?'160x600':'160x300';if(data.mode==='code'&&data.code){const box=document.createElement('aside'),frame=document.createElement('iframe');box.className=`side-ad side-ad-${side} network-ad`;box.dataset.size=size;box.setAttribute('aria-label',data.label||`Iklan ${side}`);box.innerHTML=`<span>${String(data.label||'IKLAN').replace(/[<>]/g,'')}</span>`;frame.title=data.label||`Iklan ${side}`;frame.referrerPolicy='strict-origin-when-cross-origin';frame.src=isolatedAdUrl(data.code,false);box.append(frame);box.insertAdjacentHTML('beforeend','<small>IKLAN</small>');document.body.appendChild(box);return}const link=document.createElement('a');link.className=`side-ad side-ad-${side}`;link.dataset.size=size;link.href=safeUrl(data.url);link.target='_blank';link.rel='noopener noreferrer sponsored';link.setAttribute('aria-label',data.label||`Iklan ${side}`);link.innerHTML=data.image?`<span>${String(data.label||'SPONSOR').replace(/[<>]/g,'')}</span><img src="${String(data.image).replace(/["<>]/g,'')}" alt="${String(data.label||'Iklan').replace(/["<>]/g,'')}"><small>IKLAN</small>`:`<span>${String(data.label||'RUANG IKLAN').replace(/[<>]/g,'')}</span><b>Pasang iklan<br>di sini</b><small>IKLAN</small>`;document.body.appendChild(link)}
  window.NMAds={renderPageAd};
  (async()=>{let settings;try{settings=await NMData.getSettings()}catch{return}const ads=settings.ads||{};rail('left',ads.left);rail('right',ads.right)})();
})();
